#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env.local}"  # Next.js/Template convention; never .env.example
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  case "$ENV_FILE" in *.example) warn "refusing to write a real value to $ENV_FILE"; return 1;; esac
  touch "$ENV_FILE"; chmod 600 "$ENV_FILE"   # readable by you only
  tmp=$(mktemp); chmod 600 "$tmp"
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  if git rev-parse --is-inside-work-tree >/dev/null 2>&1 && ! git check-ignore -q "$ENV_FILE"; then
    warn "$ENV_FILE is NOT ignored by git. Add it to .gitignore before committing anything."
  fi
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# parse_range "$@" (call once, after TOTAL_STAGES) lets the user run the wizard in parts:
# `bash wizard.sh 4` starts at stage 4, `bash wizard.sh 4 6` runs stages 4-6 only.
START=1; END=0   # END=0: no last stage (parse_range not called)
parse_range() {
  START="${1:-1}"; END="${2:-$TOTAL_STAGES}"
  if [[ ! "$START" =~ ^[0-9]+$ || ! "$END" =~ ^[0-9]+$ ]] \
     || (( START < 1 || END > TOTAL_STAGES || START > END )); then
    printf 'Usage: bash %s [first stage 1-%s] [last stage]\n' "$0" "$TOTAL_STAGES"; exit 1
  fi
  _STAGE_INDEX=$((START - 1))
}

# want N: wrap each stage as `if want N; then … fi`. False for stages before START;
# ends the run cleanly once past END.
want() {
  if (( END > 0 && $1 > END )); then printf '\n  Stopped after stage %s, as asked.\n\n' "$END"; exit 0; fi
  (( $1 >= START ))
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: phase 0 for this app (ROADMAP phase 0; Template README "Start a new app" steps 2–10).
# Adapted from WishJar's tested phase-0 wizard. Local values go to the local env file.
# Production values are typed in when needed, held in memory only, and handed to Supabase,
# Vercel and GitHub; never written to a file in the repo. Save every production secret in
# your password manager as you create it.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=13
parse_range "$@"

REPO_ROOT=$(git rev-parse --show-toplevel)
cd "$REPO_ROOT"
REF_FILE="supabase/.temp/project-ref"
DOMAIN="thebirthdayrun.com"
APP_NAME=$(sed -n 's/^ *name: "\(.*\)",$/\1/p' src/config/app.ts | head -n 1)
[[ -n "$APP_NAME" ]] || { warn "Couldn't read the app name from src/config/app.ts"; exit 1; }

# prod KEY "Prompt" REGEX [hint]: a production value, visible input, never saved. Reuses the
# value typed earlier in this run. Loops until it matches REGEX.
prod() {
  local key="$1" prompt="$2" re="$3" hint="${4:-}" input
  [[ -n "${!key:-}" ]] && return 0
  while true; do
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
    read -r input || { printf "\n"; warn "input ended; stopping"; exit 1; }
    input="${input#"${input%%[![:space:]]*}"}"; input="${input%"${input##*[![:space:]]}"}"
    [[ "$input" =~ $re ]] && break
    warn "that doesn't look right${hint:+ ($hint)}; try again"
  done
  printf -v "$key" '%s' "$input"
}

# prod_secret: like prod, with hidden input.
prod_secret() {
  local key="$1" prompt="$2" re="$3" hint="${4:-}" input
  [[ -n "${!key:-}" ]] && return 0
  while true; do
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
    read -rs input || { printf "\n"; warn "input ended; stopping"; exit 1; }
    printf '\n'
    input="${input#"${input%%[![:space:]]*}"}"; input="${input%"${input##*[![:space:]]}"}"
    [[ "$input" =~ $re ]] && break
    warn "that doesn't look right${hint:+ ($hint)}; try again"
  done
  printf -v "$key" '%s' "$input"
}

site_url() {
  note "Until v1 launches, use the new Vercel project's https://….vercel.app address, not $DOMAIN."
  prod SITE_URL "Production site URL (Enter: https://$DOMAIN):" '^(https://[a-z0-9.-]+/?)?$' "like https://$DOMAIN"
  SITE_URL="${SITE_URL:-https://$DOMAIN}"; SITE_URL="${SITE_URL%/}"
}
sender() {
  prod SENDER_NAME "Email sender name (Enter: $APP_NAME):" '^([A-Za-z0-9 ]{1,40})?$'
  SENDER_NAME="${SENDER_NAME:-$APP_NAME}"
  prod SENDER_ADDRESS "Sender address (Enter: hello@$DOMAIN):" '^([^@ ]+@thebirthdayrun\.com)?$' "an address on $DOMAIN"
  SENDER_ADDRESS="${SENDER_ADDRESS:-hello@$DOMAIN}"
}

project_ref() {
  [[ -f "$REF_FILE" ]] || { warn "No linked Supabase project. Run stage 3 first: bash $0 3"; exit 1; }
  REF=$(<"$REF_FILE")
}

# vercel_var NAME VALUE [sensitive]: copies VALUE to the clipboard for one Vercel env row.
vercel_var() {
  printf '%s' "$2" | wl-copy
  if [[ "${3:-}" == sensitive ]]; then
    step "Key ${BOLD}$1${RESET}: paste the value (copied), ${BOLD}Sensitive on${RESET}, Production only, Save."
  else
    step "Key ${BOLD}$1${RESET}: paste the value (copied), Production only, Save."
  fi
  pause "Saved? Enter for the next one"
}

banner "$APP_NAME phase 0: accounts, production config and deploy"

# ── 1 ──────────────────────────────────────────────────────────────────────
if want 1; then
stage "Before you start"
say "This wizard fills your local env, replaces the old Supabase project with a clean one,"
say "then walks through Resend, Cloudflare (Email Routing, Turnstile), Google, Sentry,"
say "a new Vercel project for this repo (on *.vercel.app for now), and backups. About 2 hours."
say "Stop any time; resume with: bash $0 <stage>"
say ""
say "You need:"
step "A password manager open: save every secret there as you create it. Production"
say "  secrets aren't saved by this wizard, and Resend shows its API key only once."
step "To run this in your own terminal, not through Claude, so nothing lands in a transcript."
step "Claude's app-name PR (#15, the name in src/config/app.ts) merged before stage 10,"
say "  so the first deploy shows the real app name."
say ""
note "All free tiers. Supabase Free allows 2 active projects (WishJar + thebirthdayrun);"
note "stage 3 deletes the old thebirthdayrun project first, so the new one takes its slot."
missing=()
command -v wl-copy >/dev/null || missing+=("wl-clipboard (sudo dnf install wl-clipboard)")
command -v age-keygen >/dev/null || missing+=("age (sudo dnf install age)")
gh auth status >/dev/null 2>&1 || missing+=("GitHub CLI login (gh auth login)")
[[ "$(git config core.hooksPath || true)" == ".githooks" ]] || missing+=("git hooks (git config core.hooksPath .githooks)")
[[ -d node_modules ]] || missing+=("dependencies (npm ci)")
if (( ${#missing[@]} )); then
  warn "Missing first:"; for m in "${missing[@]}"; do note "  - $m"; done; exit 1
fi
if confirm "Is $DOMAIN's DNS on Cloudflare?"; then
  write_env WIZARD_DNS_ON_CLOUDFLARE "yes"
else
  write_env WIZARD_DNS_ON_CLOUDFLARE "no"
  note "Fine: stage 4 adds Resend's records at your DNS host instead, and stage 5"
  note "(Cloudflare Email Routing) is skipped. Moving DNS to Cloudflare later is free."
fi
fi

# ── 2 ──────────────────────────────────────────────────────────────────────
if want 2; then
stage "Local development values ($ENV_FILE)"
say "Fills $ENV_FILE for LOCAL work only: the local Supabase stack, Cloudflare's"
say "test keys and Mailpit (Template README \"Local setup\" step 5). No production values here."
if ! npx supabase status -o env >/dev/null 2>&1; then
  note "Local Supabase isn't running; starting it (the first run takes a few minutes)..."
  npm run -s db:start >/dev/null
fi
status=$(npx supabase status -o env 2>/dev/null)
local_pub=$(sed -n 's/^PUBLISHABLE_KEY="\{0,1\}\([^"]*\)"\{0,1\}$/\1/p' <<<"$status")
local_sec=$(sed -n 's/^SECRET_KEY="\{0,1\}\([^"]*\)"\{0,1\}$/\1/p' <<<"$status")
[[ "$local_pub" == sb_publishable_* && "$local_sec" == sb_secret_* ]] || { warn "Couldn't read the local keys from supabase status."; exit 1; }
write_env NEXT_PUBLIC_SITE_URL "http://localhost:3000"
write_env NEXT_PUBLIC_SUPABASE_URL "http://127.0.0.1:54421"
write_env NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY "$local_pub"
write_env SUPABASE_SECRET_KEY "$local_sec"
if [[ -n "$(_existing RATE_LIMIT_HMAC_SECRET || true)" ]]; then note "kept RATE_LIMIT_HMAC_SECRET"
else write_env RATE_LIMIT_HMAC_SECRET "$(openssl rand -hex 32)"; fi
write_env NEXT_PUBLIC_TURNSTILE_SITE_KEY "1x00000000000000000000AA"
write_env TURNSTILE_SECRET_KEY "1x0000000000000000000000000000000AA"
write_env EMAIL_TRANSPORT "mailpit"
write_env MAILPIT_URL "http://127.0.0.1:54424"
write_env EMAIL_FROM "$APP_NAME Local <local@example.com>"
write_env GOOGLE_CLIENT_ID "local-placeholder"
write_env GOOGLE_CLIENT_SECRET "local-placeholder"
write_env RESEND_API_KEY "local-placeholder"
npm run -s check:supabase-env
note "Restarting local Supabase so Auth picks up the test Turnstile secret..."
npm run -s db:stop >/dev/null 2>&1 || true
npm run -s db:start >/dev/null
say "Done: npm run dev now works at http://localhost:3000."
pause
fi

# ── 3 ──────────────────────────────────────────────────────────────────────
if want 3; then
stage "Supabase: replace the old project with a clean one"
say "The restored ${BOLD}thebirthdayrun${RESET} project was never the old app's production database"
say "(that was Neon, already backed up: #163 in the legacy repo). A fresh project is cleaner"
say "than wiping: no old tables, auth users or settings left behind."
open_url "https://supabase.com/dashboard/projects"
if confirm "Is the old thebirthdayrun project already gone (deleted on 2026-10-06)?"; then
  note "Good: skipping the delete."
else
step "Open ${BOLD}thebirthdayrun${RESET} → SQL Editor and run:"
say "    select table_schema, table_name from information_schema.tables"
say "    where table_schema = 'public';"
step "Also look at Authentication → Users."
warn "If you see anything you want to keep, stop here (Ctrl-C) and tell Claude."
if confirm "Delete the old thebirthdayrun project? (cannot be undone)"; then
  step "Project Settings → General → ${BOLD}Delete project${RESET}; type its name to confirm."
  pause "Deleted? Enter to continue"
else
  warn "Stopping: stage 3 needs the old project gone (or another free slot)."; exit 1
fi
fi
open_url "https://supabase.com/dashboard/new"
step "New project: name ${BOLD}thebirthdayrun${RESET}, Free plan, region ${BOLD}East US (North Virginia)${RESET}."
step "Generate a strong database password and save it in your password manager."
step "Create, then wait until the project is ready (a minute or two)."
step "Copy the project ref: the 20 letters in the URL after /project/."
prod REF "Project ref:" '^[a-z]{20}$' "20 lowercase letters"
if ! npx supabase projects list >/dev/null 2>&1; then
  say "Logging the Supabase CLI in (opens the browser)..."
  npx supabase login
fi
say "Linking (it asks for the database password)..."
npx supabase link --project-ref "$REF"
say ""
say "Next: apply the Template's migrations to the empty production database."
if confirm "Run supabase db push now?"; then
  npx supabase db push
else
  SKIPPED+=("npx supabase db push")
fi
pause
fi

# ── 4 ──────────────────────────────────────────────────────────────────────
if want 4; then
stage "Resend: send from $DOMAIN"
open_url "https://resend.com/domains"
step "Sign in (the same account as WishJar). Add domain ${BOLD}$DOMAIN${RESET}, region us-east-1."
if [[ "$(_existing WIZARD_DNS_ON_CLOUDFLARE || true)" == "yes" ]]; then
  step "If Resend offers to set up the records on Cloudflare for you, use it. Otherwise add"
  say "  each record it lists in Cloudflare → $DOMAIN → DNS → Records, ${BOLD}Proxy: DNS only${RESET}."
else
  step "Add each record Resend lists at your DNS host (where $DOMAIN's nameservers point)."
fi
step "Back in Resend, click Verify. DNS can take a few minutes, sometimes longer."
note "Its own sending domain keeps this app's reputation separate from WishJar's (SPEC §1)."
pause "Verified (or still pending)? Enter to continue"
open_url "https://resend.com/api-keys"
step "Create API key: name ${BOLD}thebirthdayrun-production${RESET}, ${BOLD}Sending access${RESET}, domain $DOMAIN."
step "Save it in your password manager now; Resend shows it only once."
pause "Saved? Enter to continue"
fi

# ── 5 ──────────────────────────────────────────────────────────────────────
if want 5; then
stage "Cloudflare: hello@$DOMAIN (Email Routing)"
if [[ "$(_existing WIZARD_DNS_ON_CLOUDFLARE || true)" != "yes" ]]; then
  note "Skipped: $DOMAIN's DNS isn't on Cloudflare (stage 1). Use any inbox you own as the"
  note "support email for now and tell Claude which, for src/config/app.ts."
  pause
else
open_url "https://dash.cloudflare.com/?to=/:account/:zone/email/routing/overview"
step "Pick $DOMAIN if asked. Enable Email Routing and let it add its DNS records."
step "Destination addresses: your personal inbox is probably verified already (WishJar)."
step "Routing rules → Create address: ${BOLD}hello${RESET} → send to your personal inbox."
step "Send a test email to hello@$DOMAIN from another account and check it arrives."
note "This is the support email in the app config and every email footer."
pause
fi
fi

# ── 6 ──────────────────────────────────────────────────────────────────────
if want 6; then
stage "Cloudflare Turnstile widget"
open_url "https://dash.cloudflare.com/?to=/:account/turnstile"
step "Add widget: name ${BOLD}$APP_NAME${RESET}, mode ${BOLD}Managed${RESET}."
step "Hostnames: ${BOLD}$DOMAIN${RESET} and ${BOLD}localhost${RESET}."
step "Save the site key and the secret key in your password manager."
pause
fi

# ── 7 ──────────────────────────────────────────────────────────────────────
if want 7; then
stage "Google sign-in (OAuth client), and the old Maps key"
project_ref
say "First, the old app's Google Maps key: the new app uses no Google APIs (DESIGN D11),"
say "and a leftover key can still be billed if anyone has it (legacy #160)."
open_url "https://console.cloud.google.com/apis/credentials"
step "Pick the old app's Google Cloud project. Under API keys, ${BOLD}delete${RESET} the Maps key(s)."
step "APIs & Services → Enabled APIs: disable Maps JavaScript, Places and Routes/Directions."
pause "Done (or there was none)? Enter to continue"
open_url "https://console.cloud.google.com/projectcreate"
step "Create a project named ${BOLD}$APP_NAME${RESET} and select it (or reuse the old one)."
open_url "https://console.cloud.google.com/auth/overview"
step "Get started: app name ${BOLD}$APP_NAME${RESET}, support email: yours, audience ${BOLD}External${RESET}."
step "Branding → Authorized domains: add ${BOLD}$REF.supabase.co${RESET}. Skip the logo (it triggers a review)."
step "Audience → ${BOLD}Publish app${RESET} (otherwise only listed test users can sign in)."
open_url "https://console.cloud.google.com/auth/clients"
step "Create client → ${BOLD}Web application${RESET}, name $APP_NAME."
step "Authorized redirect URI: ${BOLD}https://$REF.supabase.co/auth/v1/callback${RESET}"
step "Save the client ID and client secret in your password manager."
pause
fi

# ── 8 ──────────────────────────────────────────────────────────────────────
if want 8; then
stage "Sentry (free Developer plan)"
open_url "https://sentry.io/"
step "Sign in (same org as WishJar). Create a project: platform ${BOLD}Next.js${RESET}, name ${BOLD}thebirthdayrun${RESET}."
step "Project Settings → Client Keys (DSN): save the DSN (public, but keep it handy)."
step "Note your org slug and the project slug (both are in the sentry.io URL)."
step "Optional, for readable stack traces: use the org auth token from WishJar or create one."
step "Alerts: keep the default 'email on new issue' alert."
note "The Developer plan's error quota is per org, so it's shared with WishJar (Template DESIGN §5.3)."
pause
fi

# ── 9 ──────────────────────────────────────────────────────────────────────
if want 9; then
stage "Supabase production config (auth URLs, SMTP, CAPTCHA, Google)"
project_ref
say "Fills [remotes.production] in supabase/config.toml, then runs supabase config push"
say "with your real secrets held in memory only (Template decision 0007; README step 6)."
git checkout -- supabase/config.toml   # start from the committed block on every run
site_url
open_url "https://vercel.com/account/settings"
step "Your Vercel team slug: Vercel → Settings → General (often <name>-projects)."
prod VERCEL_SCOPE "Vercel team slug:" '^[a-z0-9-]+$' "lowercase letters, digits, hyphens"
sender
say ""
say "From your password manager:"
prod_secret TURNSTILE_SECRET "Turnstile secret key:" '^0x[A-Za-z0-9_-]+$' "starts with 0x"
prod GOOGLE_ID "Google client ID:" '\.apps\.googleusercontent\.com$'
prod_secret GOOGLE_SECRET "Google client secret:" '^GOCSPX-' "starts with GOCSPX-"
prod_secret RESEND_KEY "Resend API key:" '^re_' "starts with re_"

python3 - "$REF" "$SITE_URL" "$VERCEL_SCOPE" "$SENDER_ADDRESS" "$SENDER_NAME" <<'PY'
import sys
ref, site, scope, address, name = sys.argv[1:]
path = "supabase/config.toml"
text = open(path).read()
start = text.find("# [remotes.production]")
if start < 0:
    start = text.find("[remotes.production]")
if start < 0:
    sys.exit("config.toml: no [remotes.production] block found")
block = f'''[remotes.production]
project_id = "{ref}"
[remotes.production.auth]
site_url = "{site}"
additional_redirect_urls = ["{site}/**", "https://*-{scope}.vercel.app/**"]
[remotes.production.auth.email.smtp]
enabled = true
host = "smtp.resend.com"
port = 465
user = "resend"
pass = "env(RESEND_API_KEY)"
admin_email = "{address}"
sender_name = "{name}"
'''
open(path, "w").write(text[:start] + block)
PY
printf '  %s✓ filled%s [remotes.production] in supabase/config.toml\n' "$GREEN" "$RESET"

# Move the local env file aside so the CLI sees only the real values (it reads that file too).
ASIDE="$ENV_FILE.wizard-aside"
restore_env() { if [[ -f "$ASIDE" ]]; then mv -f "$ASIDE" "$ENV_FILE"; fi; return 0; }
trap restore_env EXIT
trap 'restore_env; exit 130' INT TERM
if [[ -f "$ENV_FILE" ]]; then mv -f "$ENV_FILE" "$ASIDE"; fi
run_with_prod() {
  TURNSTILE_SECRET_KEY="$TURNSTILE_SECRET" GOOGLE_CLIENT_ID="$GOOGLE_ID" \
  GOOGLE_CLIENT_SECRET="$GOOGLE_SECRET" RESEND_API_KEY="$RESEND_KEY" "$@"
}
run_with_prod npm run -s check:supabase-env
say ""
warn "Read the diff config push shows. It should set the site URL, redirect URLs,"
warn "SMTP (smtp.resend.com), CAPTCHA (turnstile) and Google, and nothing local."
run_with_prod npx supabase config push --project-ref "$REF"
restore_env
trap - EXIT INT TERM
printf '  %s✓%s %s is back to local values\n' "$GREEN" "$RESET" "$ENV_FILE"
note "Tell Claude 'stage 9 done' so it commits the filled config.toml block (no secrets in it)."
pause
fi

# ── 10 ─────────────────────────────────────────────────────────────────────
if want 10; then
stage "Vercel: a new project for this repo, env vars, deploy"
project_ref
say "A new Vercel project, instead of rewiring the old one: the old project is set up for"
say "Vite and holds the old app's env vars (Clerk, Google Maps, API URL)."
open_url "https://vercel.com/new"
step "Import ${BOLD}janellycedenoaquino/The-Birthday-Run${RESET} (Hobby). Project name ${BOLD}thebirthdayrun${RESET}"
say "  (the old project may already use the-birthday-run). Framework: Next.js (auto)."
step "Click Deploy with no env vars. The build ${BOLD}fails${RESET} (it refuses missing env); that's expected."
pause "Imported? Enter to continue"
site_url
open_url "https://supabase.com/dashboard/project/$REF/settings/api-keys"
prod SB_PUBLISHABLE "Supabase publishable key (sb_publishable_…):" '^sb_publishable_[^[:space:]]+$'
prod_secret SB_SECRET "Supabase secret key (sb_secret_…, reveal and copy):" '^sb_secret_[^[:space:]]+$'
say "From your password manager:"
prod TURNSTILE_SITE "Turnstile site key:" '^0x[A-Za-z0-9_-]+$' "starts with 0x"
prod_secret RESEND_KEY "Resend API key:" '^re_' "starts with re_"
sender
prod SENTRY_DSN "Sentry DSN:" '^https://[^ ]+$'
prod SENTRY_ORG_SLUG "Sentry org slug:" '^[a-z0-9-]+$'
prod SENTRY_PROJECT_SLUG "Sentry project slug (Enter: thebirthdayrun):" '^([a-z0-9-]+)?$'
SENTRY_PROJECT_SLUG="${SENTRY_PROJECT_SLUG:-thebirthdayrun}"
prod_secret SENTRY_TOKEN "Sentry auth token (Enter to skip):" '^(sntrys_[^[:space:]]+)?$' "starts with sntrys_"

say ""
say "In Vercel: project ${BOLD}thebirthdayrun${RESET} → Settings → Environment Variables. Add each one"
say "with ${BOLD}only Production${RESET} ticked. Each value goes to your clipboard in turn; nothing is printed."
warn "No value may contain 127.0.0.1 or localhost (Template decision 0016)."
vercel_var NEXT_PUBLIC_SITE_URL "$SITE_URL"
vercel_var NEXT_PUBLIC_SUPABASE_URL "https://$REF.supabase.co"
vercel_var NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY "$SB_PUBLISHABLE"
vercel_var SUPABASE_SECRET_KEY "$SB_SECRET" sensitive
vercel_var RATE_LIMIT_HMAC_SECRET "$(openssl rand -hex 32)" sensitive
vercel_var NEXT_PUBLIC_TURNSTILE_SITE_KEY "$TURNSTILE_SITE"
vercel_var EMAIL_TRANSPORT "resend"
vercel_var RESEND_API_KEY "$RESEND_KEY" sensitive
vercel_var EMAIL_FROM "$SENDER_NAME <$SENDER_ADDRESS>"
vercel_var NEXT_PUBLIC_SENTRY_DSN "$SENTRY_DSN"
vercel_var SENTRY_ORG "$SENTRY_ORG_SLUG"
vercel_var SENTRY_PROJECT "$SENTRY_PROJECT_SLUG"
if [[ -n "$SENTRY_TOKEN" ]]; then vercel_var SENTRY_AUTH_TOKEN "$SENTRY_TOKEN" sensitive; fi
wl-copy --clear
note "Clipboard cleared. Not on Vercel: GOOGLE_CLIENT_* and TURNSTILE_SECRET_KEY (Supabase holds them)."
step "Settings → Deployment Protection: ${BOLD}Vercel Authentication${RESET} on for previews."
step "Analytics tab → ${BOLD}Enable${RESET} Web Analytics (free)."
say ""
warn "Don't move $DOMAIN: it stays on the birthdayrun-soon project (\"Back soon\") until v1 launches."
note "Until then the app lives at its *.vercel.app address (the site URL you entered above)."
step "Deployments → the failed one → ⋯ → ${BOLD}Redeploy${RESET}. Wait for Ready."
pause
fi

# ── 11 ─────────────────────────────────────────────────────────────────────
if want 11; then
stage "Check the live site (phase 0 \"done when\")"
site_url
open_url "$SITE_URL/sign-up"
step "The page loads on $SITE_URL, and the bot check ${BOLD}doesn't${RESET} say \"Testing only\"."
step "Sign up with your own email. The email comes from $SENDER_ADDRESS (or hello@$DOMAIN)."
step "Confirm, set a password, sign in, reach the dashboard. Sign out, then try Google."
step "Write down anything that went wrong (which screen, what it said) for Claude."
pause
fi

# ── 12 ─────────────────────────────────────────────────────────────────────
if want 12; then
stage "Backups (Template README step 10)"
KEY_FILE="$HOME/thebirthdayrun-backup-key.txt"
if [[ -f "$KEY_FILE" ]]; then
  note "Using the existing $KEY_FILE."
else
  (umask 077; age-keygen -o "$KEY_FILE" 2>/dev/null)
fi
set_var BACKUP_AGE_RECIPIENT "$(age-keygen -y "$KEY_FILE")"
warn "Move $KEY_FILE OFFLINE (USB stick plus password manager), then delete it here."
warn "Without it, no backup can ever be decrypted. Keep it apart from WishJar's key."
project_ref
open_url "https://supabase.com/dashboard/project/$REF?showConnect=true"
step "Connect → ${BOLD}Session pooler${RESET} → copy the URI and put your database password in it."
prod_secret DB_URL "Session pooler URL:" '^postgres(ql)?://[^[:space:]]+pooler\.supabase\.com:5432/[^[:space:]]+$' "the session pooler URI, port 5432"
set_secret SUPABASE_DB_URL "$DB_URL"
step "GitHub → Settings → Notifications → Actions: email on failed workflows (likely on already)."
note "Tell Claude 'stage 12 done': it turns on the daily schedule in backup.yml (on a PR)."
pause
fi

# ── 13 ─────────────────────────────────────────────────────────────────────
if want 13; then
stage "Retire the old Vercel project"
say "Only once stage 11 worked on the new project. $DOMAIN stays on birthdayrun-soon."
if confirm "Did the live site work from the new project?"; then
  open_url "https://vercel.com/dashboard"
  step "Open the ${BOLD}old${RESET} project (the one linked to The-Birthday-Run-Legacy)."
  step "Settings → General → ${BOLD}Delete Project${RESET}. This also deletes its env vars (old Clerk"
  say "  and Google keys), which is what we want."
  pause "Deleted (or kept for now)? Enter to finish"
else
  note "Skipped: keep the old project until the new one works. Re-run: bash $0 13 13"
fi
fi

finish
note "Next: tell Claude which stages are done (no values). Phase 0 is done when the"
note "Template checks pass in CI and the live site signs you in (ROADMAP phase 0)."
printf '\n'
